// Feature flags through OpenFeature (https://openfeature.dev), the vendor-neutral flag API, for Node/Next.js
// server code. Generated by `eos scaffold flags`; yours to edit. Why: .eos/packs/ref/ops/feature-flags.md
//   {{PM}} add @openfeature/server-sdk @opentelemetry/api
// Usage (server only: route handlers, server components, server actions):
//   import { flagEnabled } from "@/lib/flags";
//   if (await flagEnabled("new-checkout", { userId })) { ... }
// Values come from ops/flags.json (validated by `eos ops check`) with FLAG_<KEY> env overrides. To move to a
// flag service, swap the provider in setup(); call sites stay the same. Never ship flag logic or secret
// variants to the browser: evaluate on the server and send the result.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import {
  ErrorCode,
  type EvaluationContext,
  type Hook,
  type HookContext,
  type EvaluationDetails,
  type FlagValue,
  type JsonValue,
  OpenFeature,
  type Provider,
  type ResolutionDetails,
  StandardResolutionReasons,
} from "@openfeature/server-sdk";
import { trace } from "@opentelemetry/api";
import { createHash } from "node:crypto";

type Flag = { key: string; default?: FlagValue; rollout_percent?: number };

export const envName = (key: string) => "FLAG_" + key.replace(/[^A-Za-z0-9]/g, "_").toUpperCase();

export class RegistryProvider implements Provider {
  readonly metadata = { name: "eos-registry" } as const;
  readonly runsOn = "server" as const;
  private flags: Map<string, Flag>;

  constructor(
    file = process.env.FLAGS_FILE ?? join(process.cwd(), "{{FLAGS_REL}}"),
    private env: Record<string, string | undefined> = process.env,
  ) {
    const data = JSON.parse(readFileSync(file, "utf8")) as { flags?: Flag[] };
    this.flags = new Map((data.flags ?? []).map((f) => [f.key, f]));
  }

  private resolve<T extends FlagValue>(key: string, def: T, ctx: EvaluationContext, kind: string): ResolutionDetails<T> {
    const flag = this.flags.get(key);
    if (!flag) return { value: def, reason: StandardResolutionReasons.ERROR, errorCode: ErrorCode.FLAG_NOT_FOUND };
    const raw = this.env[envName(key)];
    let value: unknown;
    let reason: string = StandardResolutionReasons.STATIC;
    let variant = "default";
    if (raw !== undefined) {
      variant = "env";
      value = parse(raw, kind);
    } else if (kind === "boolean" && flag.rollout_percent !== undefined && flag.default !== true) {
      const target = ctx.targetingKey;
      if (!target) return { value: (flag.default ?? def) as T, reason: StandardResolutionReasons.DEFAULT, variant: "off" };
      const bucket = parseInt(createHash("sha256").update(`${key}:${target}`).digest("hex").slice(0, 8), 16) % 100;
      value = bucket < flag.rollout_percent;
      reason = StandardResolutionReasons.SPLIT;
      variant = value ? "on" : "off";
    } else {
      value = flag.default ?? def;
    }
    const ok = kind === "object" ? typeof value === "object" && value !== null : typeof value === kind;
    if (!ok) return { value: def, reason: StandardResolutionReasons.ERROR, errorCode: ErrorCode.TYPE_MISMATCH };
    return { value: value as T, reason, variant };
  }

  async resolveBooleanEvaluation(k: string, d: boolean, c: EvaluationContext) {
    return this.resolve(k, d, c, "boolean");
  }
  async resolveStringEvaluation(k: string, d: string, c: EvaluationContext) {
    return this.resolve(k, d, c, "string");
  }
  async resolveNumberEvaluation(k: string, d: number, c: EvaluationContext) {
    return this.resolve(k, d, c, "number");
  }
  async resolveObjectEvaluation<T extends JsonValue>(k: string, d: T, c: EvaluationContext) {
    return this.resolve(k, d, c, "object");
  }
}

function parse(raw: string, kind: string): unknown {
  const low = raw.trim().toLowerCase();
  if (kind === "boolean") return ["1", "true", "on", "yes"].includes(low) ? true : ["0", "false", "off", "no"].includes(low) ? false : undefined;
  if (kind === "number") return Number.isFinite(Number(raw)) && raw.trim() !== "" ? Number(raw) : undefined;
  if (kind === "object") {
    try {
      return JSON.parse(raw);
    } catch {
      return undefined;
    }
  }
  return raw;
}

// Adds a feature_flag.evaluation event to the active span (OpenTelemetry semantic conventions, Development).
export class TraceHook implements Hook {
  after(hookContext: Readonly<HookContext>, details: EvaluationDetails<FlagValue>) {
    const span = trace.getActiveSpan();
    if (!span?.isRecording()) return;
    span.addEvent("feature_flag.evaluation", {
      "feature_flag.key": details.flagKey,
      "feature_flag.provider.name": hookContext.providerMetadata.name,
      "feature_flag.result.reason": (details.reason ?? "unknown").toLowerCase(),
      ...(details.variant ? { "feature_flag.result.variant": details.variant } : {}),
    });
  }
}

let ready: Promise<void> | undefined;
let hooked = false;
export function setup(provider: Provider = new RegistryProvider()): Promise<void> {
  if (!hooked) {
    OpenFeature.addHooks(new TraceHook()); // once, even if setup runs again
    hooked = true;
  }
  ready = OpenFeature.setProviderAndWait(provider);
  return ready;
}

/** True when the boolean flag is on for this user. Unknown flag or provider error: `fallback`. */
export async function flagEnabled(key: string, opts: { userId?: string; fallback?: boolean } = {}): Promise<boolean> {
  await (ready ?? setup());
  return OpenFeature.getClient().getBooleanValue(key, opts.fallback ?? false, opts.userId ? { targetingKey: opts.userId } : {});
}
